import React from "react";
import { Content } from "@prismicio/client";
import { SliceComponentProps, PrismicRichText, PrismicNextLink } from "@prismicio/react";
import {
  FaFacebookF,
  FaTwitter,
  FaInstagram,
  FaYoutube,
  FaLinkedinIn,
} from "react-icons/fa";
import { FaArrowUp } from "react-icons/fa6";

export type MultiColumnFooterProps = SliceComponentProps<Content.MultiColumnFooterSlice>;

export default function MultiColumnFooter({ slice }: MultiColumnFooterProps): JSX.Element {
  const columns = slice.primary.columns || [];

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const renderSocialIcon = (variant?: string) => {
    switch (variant?.toLowerCase()) {
      case "facebook":
        return <FaFacebookF className="w-4 h-4" />;
      case "twitter":
        return <FaTwitter className="w-4 h-4" />;
      case "instagram":
        return <FaInstagram className="w-4 h-4" />;
      case "youtube":
        return <FaYoutube className="w-4 h-4" />;
      case "linkedin":
        return <FaLinkedinIn className="w-4 h-4" />;
      default:
        return null;
    }
  };

  return (
    <footer className="bg-[#030914] text-slate-300 pt-16 pb-12 px-6 md:px-12 lg:px-20 relative font-sans">
      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-10 pb-16 border-b border-slate-800/60">
        {columns.map((col, index) => {
          return (
            <div key={index} className="flex flex-col space-y-4">
              {/* Column Heading */}
              {col.heading && (
                <div className="text-[#00c8c8] text-xl font-medium tracking-wide mb-2">
                  <PrismicRichText field={col.heading} />
                </div>
              )}

              {/* Column Description */}
              {col.description && (
                <div className="text-sm leading-relaxed text-slate-300">
                  <PrismicRichText field={col.description} />
                </div>
              )}

              {/* Contact Info Type */}
              {col.type === "contact_info" && (
                <div className="space-y-4 text-sm leading-relaxed text-slate-300">
                  {col.address && (
                    <p className="whitespace-pre-line">{col.address}</p>
                  )}
                  {col.secondary_contact && (
                    <p>{col.secondary_contact}</p>
                  )}
                  
                  {/* Social Icons inside Contact Info if provided */}
                  {Array.isArray(col.social_icons) && col.social_icons.length > 0 && (
                    <div className="flex items-center space-x-4 pt-2">
                      {col.social_icons.map((social, idx) => (
                        <PrismicNextLink
                          key={idx}
                          field={social}
                          className="text-[#00c8c8] hover:text-white transition-colors duration-200"
                        >
                          {renderSocialIcon((social as any).variant)}
                        </PrismicNextLink>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {/* Custom Links or Navigation Links */}
              {(col.type === "navigation_links" || col.type === "social_links" || col.type === "custom") && (
                <div className="flex flex-col space-y-2 text-sm">
                  {col.custom_links_heading && (
                    <div className="font-medium text-white mb-1">
                      <PrismicRichText field={col.custom_links_heading} />
                    </div>
                  )}

                  {Array.isArray(col.custom_links) &&
                    col.custom_links.map((link, linkIdx) => (
                      <PrismicNextLink
                        key={linkIdx}
                        field={link}
                        className="text-slate-300 hover:text-white transition-colors duration-200 w-fit"
                      >
                        {col.custom_link_label || link.text}
                      </PrismicNextLink>
                    ))}
                </div>
              )}

              {/* Newsletter Signup Type */}
              {col.type === "newsletter_signup" && (
                <div className="flex flex-col space-y-4 text-sm">
                  {col.newsletter_text && (
                    <div className="text-slate-300 leading-relaxed">
                      <PrismicRichText field={col.newsletter_text} />
                    </div>
                  )}

                  <form
                    onSubmit={(e) => e.preventDefault()}
                    className="flex flex-col space-y-3 pt-2"
                  >
                    <label htmlFor={`email-input-${index}`} className="text-slate-300 font-medium">
                      Email
                    </label>
                    <input
                      id={`email-input-${index}`}
                      type="email"
                      placeholder={col.email_placeholder || ""}
                      className="bg-slate-100 text-slate-900 px-4 py-2 rounded focus:outline-none focus:ring-2 focus:ring-[#00c8c8] w-full"
                    />
                    <button
                      type="submit"
                      className="bg-slate-700 hover:bg-slate-600 text-white font-medium px-6 py-2 rounded-full w-fit transition-colors duration-200"
                    >
                      {col.submit_button_label || "Subscribe"}
                    </button>
                  </form>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Footer Bottom Bar */}
      <div className="max-w-7xl mx-auto pt-8 flex items-center justify-between text-xs text-slate-400">
        <div className="w-full text-center">
          <p>Copyright © {new Date().getFullYear()} SymVentra.</p>
        </div>

        {/* Scroll to Top Button */}
        <button
          onClick={scrollToTop}
          aria-label="Scroll to top"
          className="fixed bottom-6 right-6 bg-[#1a73e8] hover:bg-blue-600 text-white p-3.5 rounded-full shadow-lg transition-transform duration-200 hover:scale-105"
        >
          <FaArrowUp className="w-5 h-5" />
        </button>
      </div>
    </footer>
  );
}